// Helper: déduire le genre depuis le nom complet du joueur
export function inferGender(firstName: string, lastName: string): 'M' | 'F' | undefined {
  const full1 = `${firstName} ${lastName}`.toLowerCase().trim();
  const full2 = `${lastName} ${firstName}`.toLowerCase().trim();
  if (RANKING_GENDER_MAP[full1]) return RANKING_GENDER_MAP[full1];
  if (RANKING_GENDER_MAP[full2]) return RANKING_GENDER_MAP[full2];
  // Déduction par prénom exclusivement féminin
  if (WOMEN_FIRSTNAMES.has(firstName.toLowerCase())) return 'F';
  return undefined;
}

// Helper: déduire la division depuis le nom complet
export function inferDivision(firstName: string, lastName: string): string | undefined {
  const full1 = `${firstName} ${lastName}`.toLowerCase().trim();
  const full2 = `${lastName} ${firstName}`.toLowerCase().trim();
  return RANKING_DIV_MAP[full1] ?? RANKING_DIV_MAP[full2];
}
